import { test } from 'node:test';
import assert from 'node:assert/strict';
import express from 'express';
import { notesRouter } from '../src/routes/notes.js';
import { createStore } from '../src/store.js';
import { createSession } from '../src/auth/middleware.js';

async function withServer(fn) {
  const app = express();
  app.use('/notes', notesRouter(createStore()));
  const server = app.listen(0);
  const base = `http://127.0.0.1:${server.address().port}/notes`;
  const token = createSession(1);
  const post = (body) => fetch(base, {
    method: 'POST',
    headers: { 'content-type': 'application/json', authorization: `Bearer ${token}` },
    body: JSON.stringify(body),
  });
  try { await fn(post); } finally { server.close(); }
}

test('POST /notes accepts a valid note', () => withServer(async (post) => {
  const res = await post({ title: ' hi ', body: 'x', tags: ['a'] });
  assert.equal(res.status, 201);
  assert.equal((await res.json()).title, 'hi');
}));

test('POST /notes rejects invalid bodies', () => withServer(async (post) => {
  for (const [body, msg] of [
    [{}, 'title is required'],
    [{ title: '   ' }, 'title is required'],
    [{ title: 'a'.repeat(121) }, 'title must be at most 120 characters'],
    [{ title: 'a', body: 5 }, 'body must be a string'],
    [{ title: 'a', tags: [1] }, 'tags must be a list of strings'],
    [{ title: 'a', tags: 'x' }, 'tags must be a list of strings'],
  ]) {
    const res = await post(body);
    assert.equal(res.status, 400, JSON.stringify(body));
    assert.deepEqual((await res.json()).errors, [msg]);
  }
}));
